solution:
def count_components(graph):
    visited = set()

    def dfs(node):
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                dfs(neighbor)

    count = 0
    for node in graph:
        if node not in visited:
            count += 1
            dfs(node)
    return count
